// Torus Flow - a silky, self-warping flow of sines with a glowing palette.
// Parametric (u,v), animated. Seam-free on any closed surface.
//
// HOW IT CLOSES: (u,v) is placed on the flat torus of 4D space,
//     (cos 2pi u, sin 2pi u, cos 2pi v, sin 2pi v),
// and the whole pattern is computed there. Going once around u or v brings
// the point back exactly where it started, so there is nothing to join: no
// seam at any density, no whole-number constraints. Twisted gluing (Klein
// bottle, Moebius band): set MIRROR_V to 1.0.
// Each octave pushes the point along sines of itself (domain warping), adds
// |cos(p) . sin(p')| and then turns the point in 4D and scales it up.
// Technique family: domain-warped sums of sines ("cyclic noise"); this code
// is written from scratch.
// Dock colors: u_col1 = tint of the palette (white = as is),
//              u_col2 = glow of the dark valleys (black = none).

const float SCALE    = 2.0;    // pattern density                       [1 .. 6]
const float ASPECT_V = 1.0;    // density along v relative to u         [0.3 .. 2]
const int   OCTAVES  = 7;      // detail                                [3 .. 9]
const float WARP     = 0.35;   // self-distortion per octave            [0 .. 0.6]
const float SPEED    = 0.35;   // flow speed (0 = still)
const float DRIFT    = 0.01;   // slow slide along u (turns per second)
const float HUE_RATE = 1.4;    // color turns over the flow range       [0.5 .. 3]
const vec3  PALETTE  = vec3(0.0, 0.1, 0.2); // R,G,B phases: (0,0.1,0.2) ice & fire,
                               // (0,0.33,0.67) rainbow, (0.55,0.62,0.72) steel & amber
const float GLOW     = 1.2;    // higher = darker valleys, brighter streams [0.5 .. 3]
const float DOCK_MIX = 0.0;    // 0 = palette above, 1 = dock colors only
const float MIRROR_U = 0.0;    // 1 = fold u
const float MIRROR_V = 0.0;    // 1 = fold v (Klein bottle, Moebius band)

vec2 seamFold(vec2 q) {
    vec2 tri = 0.5 - abs(fract(q) - 0.5);
    return mix(q, tri, vec2(MIRROR_U, MIRROR_V));
}

vec4 torusPoint(vec2 uv) {
    vec2 a = TAU * uv;
    return SCALE * vec4(cos(a.x), sin(a.x), ASPECT_V * cos(a.y), ASPECT_V * sin(a.y));
}

// fixed 4D turn between octaves: four plane rotations mix all the axes
vec4 turn4(vec4 p) {
    p.xz = mat2(0.80, 0.60, -0.60, 0.80) * p.xz;
    p.yw = mat2(0.28, 0.96, -0.96, 0.28) * p.yw;
    p.xy = mat2(0.96, -0.28, 0.28, 0.96) * p.xy;
    p.zw = mat2(0.60, -0.80, 0.80, 0.60) * p.zw;
    return p;
}

float sineFlow(vec4 p, float time) {
    float acc = 0.0;
    float amp = 1.0;
    float norm = 0.0;
    float freq = 1.7;
    for (int i = 0; i < OCTAVES; i++) {
        p += WARP * sin(p.wxyz * freq + time * (0.6 + 0.21 * float(i)));
        acc += amp * abs(dot(cos(p), sin(p.zwxy)));
        norm += amp;
        amp *= 0.7;
        freq *= 1.31;
        p = 1.47 * turn4(p);
    }
    return acc / norm;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = seamFold(fragCoord / iResolution.xy);
    uv.x += iTime * DRIFT;

    float f = sineFlow(torusPoint(uv), iTime * SPEED);
    float k = clamp(f / 1.3, 0.0, 1.0);

    // cosine palette along the flow value, brightness rising with it: the
    // streams glow, the valleys between them sink into the dark
    vec3 pal = 0.5 + 0.5 * cos(TAU * (HUE_RATE * f + PALETTE));
    vec3 col = pal * (0.12 + 0.88 * pow(k, GLOW)) * 1.25 * u_col1 + u_col2 * 0.5 * (1.0 - k);
    vec3 dock = mix(u_col2, u_col1, smoothstep(0.15, 1.0, k));
    col = mix(col, dock, DOCK_MIX);

    fragColor = vec4(min(col, vec3(1.0)), 1.0);
}
